/* Live owner workspace. The sample dashboard remains a separate experience. */
window.OwnerApp = (() => {
  const pages = { teach: 'Teach Zotoz', playbook: 'My Playbook', approvals: 'Approvals', activity: 'Activity', brief: 'Daily Brief' };
  const ui = { loaded: false, loading: false, busy: false, error: '', connections: null, data: null, email: '', sent: false, profileDraft: null, bookDraft: null, caseDraft: null, reviewDrafts: {}, filter: 'pending' };
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  const date = value => new Date(value).toLocaleString(undefined, { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' });
  const redraw = () => { if (typeof render === 'function' && pages[location.hash.slice(1)]) render(); };
  const doc = () => ui.data?.document;
  const notice = () => ui.error ? `<div class="owner-error" role="alert">${esc(ui.error)} <button type="button" data-owner="refresh">Refresh workspace</button></div>` : '';
  async function api(action, payload, method = 'POST') {
    const response = await fetch(method === 'GET' ? `/api/owner?action=${action}` : '/api/owner', { method, credentials:'same-origin', headers: method === 'POST' ? { 'Content-Type':'application/json' } : {}, ...(method === 'POST' ? { body:JSON.stringify({ action, ...payload }) } : {}) });
    let data; try { data = await response.json(); } catch { throw new Error('The live workspace service is not available yet. Please try again later.'); }
    if (!response.ok) { const error = new Error(data.error || 'Could not complete this request.'); error.status = response.status; throw error; }
    return data;
  }
  async function load() {
    if (ui.loading) return;
    ui.loading = true;
    try {
      ui.connections = (await api('status', null, 'GET')).connections;
      if (ui.connections.database && ui.connections.owners) {
        try { ui.data = await api('workspace', null, 'GET'); } catch (error) { if (error.status !== 401) throw error; ui.data = null; }
      }
    } catch (error) { ui.error = error.message; }
    finally { ui.loaded = true; ui.loading = false; redraw(); }
  }
  async function mutate(action, payload = {}, destination) {
    if (ui.busy) return;
    ui.busy = true; ui.error = ''; redraw();
    try {
      ui.data = await api(action, { revision: ui.data.revision, ...payload });
      if (action === 'saveProfile') ui.profileDraft = null;
      if (action === 'activatePlaybook' || action === 'generatePlaybook') ui.bookDraft = null;
      if (action === 'evaluateCase') { ui.caseDraft = null; if (payload.id) delete ui.reviewDrafts[payload.id]; }
      if (action === 'decideCase') delete ui.reviewDrafts[payload.id];
      if (destination) location.hash = destination;
      toast({ saveProfile:'Your interview is saved.', generatePlaybook:'Your draft playbook is ready for review.', activatePlaybook:'Playbook approved. Zotoz will use these rules.', evaluateCase:'Recommendation ready. Nothing has been sent.', decideCase:'Your decision is saved. No customer message was sent.', generateBrief:'Your daily brief is ready.' }[action]);
      return true;
    } catch (error) { ui.error = error.message; if (error.status === 401) ui.data = null; return false; }
    finally { ui.busy = false; redraw(); }
  }
  const button = (label, action, secondary = false, disabled = false) => `<button type="button" class="btn ${secondary?'btn-light':'btn-dark'}" data-owner="${action}" ${ui.busy||disabled?'disabled':''}>${esc(label)}</button>`;
  const intro = (eyebrow, title, description) => `<div class="owner-intro"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div>`;
  function authPage() {
    const ready = ui.connections?.database && ui.connections?.owners;
    return `<div class="owner-auth">${intro('YOUR BUSINESS. YOUR WAY.','An agent that learns from you.','Teach Zotoz how you decide. Review its recommendations. Stay in control without handling every detail.')}<section class="panel owner-auth-card">${!ui.loaded?'<p role="status">Connecting to your owner workspace…</p>':ready?`<h2>${ui.sent?'Check your inbox.':'Sign in to your workspace'}</h2><p>${ui.sent?'Open the secure sign-in link in your email. It will bring you back here.':'Enter your invited email address. We’ll send you a secure sign-in link.'}</p><form data-owner-form="login"><label class="field-label" for="owner-email">Work email</label><input class="owner-input" id="owner-email" name="email" type="email" autocomplete="email" value="${esc(ui.email)}" maxlength="254" required><button class="btn btn-dark" ${ui.busy?'disabled':''}>${ui.busy?'Sending…':ui.sent?'Send another link':'Email me a sign-in link'}</button></form>`:`<span class="owner-connect-icon">${icon('shield')}</span><h2>Your live workspace is being connected.</h2><p>Owner sign-in and business storage need to be connected before you can save your playbook. The sample dashboard is available to explore.</p><a class="btn btn-light" href="#overview">Explore the sample dashboard ${icon('right')}</a>`}</section><div class="owner-principles"><span>${icon('shield')} Private owner workspace</span><span>${icon('tasks')} Your rules, reviewed by you</span><span>${icon('check')} No messages sent without you</span></div></div>`;
  }
  const field = (key,label,hint,value,short = false) => `<label class="owner-field"><span>${label}</span>${hint?`<small>${hint}</small>`:''}${short?`<input class="owner-input" name="${key}" value="${esc(value)}" maxlength="120" required>`:`<textarea class="field" name="${key}" rows="4" maxlength="4000" required>${esc(value)}</textarea>`}</label>`;
  function teach() {
    const p = ui.profileDraft || doc().profile || {};
    return `${intro('01 / TEACH ZOTOZ','Nobody knows your business like you.','Share how you work and how you make decisions. Your answers become a draft playbook for you to review.')}<form data-owner-form="profile"><section class="panel owner-section"><div class="owner-section-heading"><span>01</span><div><h2>The business you’ve built</h2><p>Start with the facts Zotoz should know.</p></div></div><div class="owner-form-grid">${field('businessName','Business name','',p.businessName,true)}${field('ownerName','Your name','',p.ownerName,true)}${field('industry','Industry or type of business','',p.industry,true)}${field('tone','How should your business sound?','For example: warm, direct, professional; English and Hindi.',p.tone,true)}</div>${field('products','What do you sell, and to whom?','Include your main products or services and typical customers.',p.products)}</section><section class="panel owner-section"><div class="owner-section-heading"><span>02</span><div><h2>How you make the call</h2><p>Real examples are more useful than perfect answers.</p></div></div>${field('pricing','How do you price and negotiate?','Include discount limits, margin requirements, payment terms, and when you make exceptions.',p.pricing)}${field('decisions','Walk us through a recent decision.','What did the customer ask? What did you decide, and why? Include a situation where you said no.',p.decisions)}${field('priorities','What matters most to you?','For example: reliable delivery before growth, long-term relationships, or protecting margins.',p.priorities)}</section><section class="panel owner-section"><div class="owner-section-heading"><span>03</span><div><h2>Where you draw the line</h2><p>Make ownership and escalation clear.</p></div></div>${field('delegation','Who handles what?','List the people or roles responsible for sales, operations, and accounts, and what they may decide.',p.delegation)}${field('escalation','What should always come back to you?','What should interrupt your holiday? What should Zotoz never assume or promise?',p.escalation)}</section><div class="owner-savebar"><p>Saved to your private workspace. AI processing starts only when you generate a playbook.</p><button class="btn btn-dark" ${ui.busy?'disabled':''}>${ui.busy?'Saving…':'Save my interview'} ${icon('right')}</button></div></form>${doc().profile?`<div class="owner-next"><div><h2>Ready to turn your answers into rules?</h2><p>You’ll review every rule before it becomes active.</p></div>${button('Generate my playbook','generate',false,!ui.connections.ai)}</div>`:''}`;
  }
  function playbook() {
    const book = ui.bookDraft || doc().draftPlaybook || doc().playbook;
    return `${intro('02 / MY PLAYBOOK','Your judgment, written down.','Review the rules Zotoz will use. Nothing becomes active until you approve it.')}<div class="owner-toolbar"><span class="pill">${doc().playbook?`Active: version ${doc().playbook.version}`:'No active playbook'}</span>${button('Generate from my interview','generate',true,!doc().profile||!ui.connections.ai)}</div>${!book?`<section class="panel owner-empty">${icon('tasks')}<h2>Your playbook starts with your experience.</h2><p>Complete the owner interview, then ask Zotoz to propose a set of rules.</p><a href="#teach" class="btn btn-dark">Teach Zotoz ${icon('right')}</a></section>`:`<form data-owner-form="playbook"><section class="panel owner-section"><p class="owner-section-tag">${doc().draftPlaybook?'DRAFT · REVIEW REQUIRED':'OWNER-APPROVED · EDIT TO CREATE A NEW VERSION'}</p><label class="owner-field"><span>Business summary</span><textarea class="field" name="summary" maxlength="2000" required>${esc(book.summary)}</textarea></label><label class="owner-field"><span>Communication style</span><textarea class="field" name="voice" maxlength="1000" required>${esc(book.voice)}</textarea></label><label class="owner-field"><span>Priorities · one per line</span><textarea class="field" name="priorities" maxlength="5000" required>${esc(book.priorities.join('\n'))}</textarea></label></section>${book.rules.map((r,i)=>`<section class="panel owner-section owner-rule"><div class="owner-rule-heading"><span class="pill">RULE ${i+1}</span><span class="record-meta">Owner review required for every recommendation</span></div><label class="owner-field"><span>Rule title</span><input class="owner-input" name="title-${i}" maxlength="120" value="${esc(r.title)}" required></label><label class="owner-field"><span>What should Zotoz do?</span><textarea class="field" name="instruction-${i}" maxlength="1600" required>${esc(r.instruction)}</textarea></label><label class="owner-field"><span>When should it ask you?</span><textarea class="field" name="escalateWhen-${i}" maxlength="1000" required>${esc(r.escalateWhen)}</textarea></label><p class="owner-source"><strong>Source:</strong> ${esc(r.source)}</p></section>`).join('')}${book.unknowns.length?`<section class="owner-open-questions"><h2>Still needs your input</h2><ul>${book.unknowns.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><p>Clarify these in your interview or rules. Missing facts must remain escalation conditions.</p></section>`:''}<div class="owner-savebar"><p>Approving creates a new version. Pending requests must be re-evaluated against it.</p><button class="btn btn-dark" ${ui.busy?'disabled':''}>Approve this playbook ${icon('check')}</button></div></form>`}`;
  }
  function approvals() {
    const cases = doc().cases.filter(c => ui.filter === 'all' || c.status === ui.filter).slice().reverse();
    const draft = ui.caseDraft || {};
    return `${intro('03 / APPROVALS','Your agent suggests. You decide.','Bring in a real customer request. Zotoz will apply your approved playbook and explain its recommendation.')}<section class="panel owner-section"><h2>A new customer request</h2><form data-owner-form="case"><label class="owner-field"><span>Customer or company</span><input class="owner-input" name="customer" maxlength="160" value="${esc(draft.customer)}" placeholder="Customer name" required></label><label class="owner-field"><span>What are they asking?</span><textarea class="field" name="request" maxlength="8000" placeholder="Paste the customer’s request here…" required>${esc(draft.request)}</textarea></label><label class="owner-field"><span>Verified facts Zotoz can use</span><small>Relevant prices, costs, stock, customer history, or deadlines. Leave unknown facts out.</small><textarea class="field" name="facts" maxlength="4000" placeholder="For example: quoted price ₹85,000; repeat customer; current stock confirmed by Rahul.">${esc(draft.facts)}</textarea></label><div class="owner-savebar"><p>${doc().playbook?'Uses your active playbook. Customer content cannot change your rules.':'Approve your playbook before requesting a recommendation.'}</p><button class="btn btn-dark" ${ui.busy||!doc().playbook||!ui.connections.ai?'disabled':''}>${ui.busy?'Preparing recommendation…':'Ask my agent'} ${icon('spark')}</button></div></form></section><div class="owner-toolbar"><h2>Decision queue</h2><div class="filter-tabs">${['pending','approved','rejected','all'].map(f=>`<button data-owner-filter="${f}" class="${ui.filter===f?'selected':''}" aria-pressed="${ui.filter===f}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div></div>${cases.length?cases.map(c=>`<section class="panel owner-section owner-case"><div class="owner-case-heading"><div><h2>${esc(c.customer)}</h2><p>${date(c.createdAt)} · Playbook v${c.playbookVersion}</p></div><span class="pill ${c.status==='pending'?'amber':''}">${c.status==='approved'?'Draft approved · not sent':c.status}</span></div><blockquote>${esc(c.request)}</blockquote><h3>Suggested action</h3><p>${esc(c.proposal.summary)}</p><h3>Why this fits your rules</h3><p>${esc(c.proposal.explanation)}</p><div class="owner-rule-tags">${c.proposal.ruleIds.map(id=>`<span class="pill">${esc(id)}</span>`).join('')}</div>${c.proposal.missingFacts.length?`<div class="owner-open-questions"><h3>Check before using this reply</h3><ul>${c.proposal.missingFacts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`:''}${c.status==='pending'?c.playbookVersion!==doc().playbook?.version?`<div class="owner-stale">Your playbook changed. Re-evaluate before making a decision.</div><button class="btn btn-dark" data-owner-reevaluate="${c.id}" ${ui.busy?'disabled':''}>Re-evaluate request</button>`:`<form data-owner-form="decision" data-id="${c.id}"><label class="owner-field"><span>Review and edit the reply</span><textarea class="field" name="reply" maxlength="6000" required>${esc(ui.reviewDrafts[c.id]?.reply ?? c.proposal.draftReply)}</textarea></label><label class="owner-field"><span>Your feedback</span><small>Required when rejecting. Feedback can inform your next draft playbook.</small><textarea class="field" name="note" maxlength="3000" placeholder="What would you do differently?">${esc(ui.reviewDrafts[c.id]?.note || '')}</textarea></label><div class="owner-decision-actions"><button class="btn btn-dark" name="decision" value="approved" ${ui.busy?'disabled':''}>Approve draft ${icon('check')}</button><button class="btn btn-light" name="decision" value="rejected" ${ui.busy?'disabled':''}>Reject & give feedback</button></div></form>`:`${c.approvedReply?`<div class="message-original">${esc(c.approvedReply)}</div><button class="btn btn-light" data-owner-copy="${c.id}">Copy approved reply</button>`:''}${c.ownerNote?`<p class="owner-source"><strong>Your feedback:</strong> ${esc(c.ownerNote)}</p>`:''}`}</section>`).join(''):`<section class="panel owner-empty">${icon('check')}<h2>${ui.filter==='pending'?'Nothing waiting on you.':'No decisions here yet.'}</h2><p>Your saved customer requests and decisions will appear here.</p></section>`}`;
  }
  function activity() { return `${intro('04 / ACTIVITY','See what happened. And why.','A record of saved interviews, playbook versions, AI recommendations, and your decisions.')}<section class="panel owner-timeline">${doc().activity.length?doc().activity.map(a=>`<article><span class="owner-timeline-icon">${icon('check')}</span><div><h2>${esc(a.title)}</h2><p>${esc(a.detail)}</p><time>${date(a.at)}</time></div></article>`).join(''):'<div class="owner-empty"><h2>Your story starts here.</h2><p>Save your owner interview to begin your activity history.</p></div>'}</section>`; }
  function brief() { const b=doc().brief; return `${intro('05 / DAILY BRIEF','A little context. A lot of clarity.','A short report based on your saved requests and decisions. No sample sales or invented business metrics.')}<div class="owner-summary-grid"><div class="panel"><span>Awaiting your decision</span><strong>${doc().cases.filter(c=>c.status==='pending').length}</strong></div><div class="panel"><span>Drafts approved</span><strong>${doc().cases.filter(c=>c.status==='approved').length}</strong></div><div class="panel"><span>Active playbook</span><strong>${doc().playbook?`v${doc().playbook.version}`:'—'}</strong></div></div><div class="owner-toolbar"><p>${b?`Generated ${date(b.generatedAt)}`:'Your next update, when you need it.'}</p>${button(ui.busy?'Preparing your brief…':'Generate my brief','brief',false,!ui.connections.ai)}</div>${b?`<section class="panel owner-section owner-brief"><span class="assistant-avatar">${icon('spark')}</span><h2>Your business, in a few words.</h2><p class="owner-brief-summary">${esc(b.summary)}</p>${[['needsAttention','Needs your attention'],['handled','Decisions made'],['nextSteps','What comes next']].map(([key,label])=>`<h3>${label}</h3>${b[key].length?`<ul>${b[key].map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:'<p>Nothing to report yet.</p>'}`).join('')}</section>`:`<section class="panel owner-empty">${icon('sun')}<h2>Your daily brief is ready to be written.</h2><p>It will summarise the activity in your workspace when you ask.</p></section>`}`; }
  function shell(page) {
    const pending = doc()?.cases.filter(c=>c.status==='pending').length || 0;
    return `<div class="owner-shell"><header class="owner-header">${brand()}<div>${ui.data?`<span>${esc(doc().profile?.businessName || 'Your owner workspace')}</span><button class="btn btn-light btn-small" data-owner="logout">Sign out</button>`:'<a href="#overview" class="btn-text">Explore the demo</a>'}</div></header><div class="owner-layout"><aside class="owner-sidebar"><p class="nav-label">YOUR OWNER AGENT</p><nav>${Object.entries(pages).map(([key,label],i)=>`<a class="nav-item ${key===page?'active':''}" href="#${key}" ${key===page?'aria-current="page"':''}>${icon(['spark','tasks','shield','clock','sun'][i])}${label}${key==='approvals'&&pending?`<span class="nav-count">${pending}</span>`:''}</a>`).join('')}</nav><div class="owner-mode"><span class="pill">Owner approval mode</span><p>Zotoz recommends.<br>You approve and send.</p></div></aside><main class="owner-content" id="main" tabindex="-1">${notice()}${ui.busy?'<div class="owner-working" role="status">Working on your request. This may take a moment…</div>':''}${!ui.data?authPage():`${!ui.connections.ai?'<div class="owner-stale">Your interview and playbook can be saved. AI recommendations will be available when the AI connection is configured.</div>':''}${({teach,playbook,approvals,activity,brief})[page]()}`}</main></div></div>`;
  }
  function captureProfile(form) { return Object.fromEntries(new FormData(form)); }
  function captureBook(form) { const base=ui.bookDraft||doc().draftPlaybook||doc().playbook; const f=new FormData(form); return {...base,summary:f.get('summary'),voice:f.get('voice'),priorities:String(f.get('priorities')).split('\n').map(s=>s.trim()).filter(Boolean),rules:base.rules.map((r,i)=>({...r,title:f.get(`title-${i}`),instruction:f.get(`instruction-${i}`),escalateWhen:f.get(`escalateWhen-${i}`)}))}; }
  document.addEventListener('input', e=>{const f=e.target.closest('[data-owner-form]');if(!f)return;if(f.dataset.ownerForm==='profile')ui.profileDraft=captureProfile(f);if(f.dataset.ownerForm==='playbook')ui.bookDraft=captureBook(f);if(f.dataset.ownerForm==='case')ui.caseDraft=captureProfile(f);if(f.dataset.ownerForm==='decision')ui.reviewDrafts[f.dataset.id]=captureProfile(f)});
  document.addEventListener('submit', async e=>{
    const form=e.target.closest('[data-owner-form]');if(!form)return;e.preventDefault();if(ui.busy)return;
    const f=new FormData(form);
    if(form.dataset.ownerForm==='login') { ui.email=String(f.get('email'));ui.busy=true;ui.error='';redraw();try{await api('login',{email:ui.email});ui.sent=true}catch(error){ui.error=error.message}finally{ui.busy=false;redraw()}return; }
    if(form.dataset.ownerForm==='profile'){ui.profileDraft=captureProfile(form);await mutate('saveProfile',{profile:ui.profileDraft});}
    if(form.dataset.ownerForm==='playbook'){ui.bookDraft=captureBook(form);await mutate('activatePlaybook',{playbook:ui.bookDraft},'approvals');}
    if(form.dataset.ownerForm==='case'){ui.caseDraft=captureProfile(form);await mutate('evaluateCase',{case:ui.caseDraft});}
    if(form.dataset.ownerForm==='decision') { const decision=e.submitter?.value;if(decision==='rejected'&&!String(f.get('note')).trim()){form.elements.note.setCustomValidity('Explain what should be different.');form.elements.note.reportValidity();form.elements.note.oninput=()=>form.elements.note.setCustomValidity('');return}await mutate('decideCase',{id:form.dataset.id,decision,reply:f.get('reply'),note:f.get('note')}); }
  });
  document.addEventListener('click', async e=>{
    const filter=e.target.closest('[data-owner-filter]');if(filter){ui.filter=filter.dataset.ownerFilter;redraw();return}
    const retry=e.target.closest('[data-owner-reevaluate]');if(retry){await mutate('evaluateCase',{id:retry.dataset.ownerReevaluate});return}
    const copy=e.target.closest('[data-owner-copy]');if(copy){try{await navigator.clipboard.writeText(doc().cases.find(c=>c.id===copy.dataset.ownerCopy).approvedReply);toast('Approved reply copied. You can send it through your business channel.')}catch{toast('Could not copy. Select the approved reply and copy it manually.')}return}
    const el=e.target.closest('[data-owner]');if(!el||ui.busy)return;
    if(el.dataset.owner==='generate')await mutate('generatePlaybook',{},'playbook');
    if(el.dataset.owner==='brief')await mutate('generateBrief');
    if(el.dataset.owner==='refresh'){ui.error='';ui.loaded=false;load();redraw();}
    if(el.dataset.owner==='logout'){try{await api('logout');ui.data=null;ui.profileDraft=null;ui.bookDraft=null;ui.caseDraft=null;ui.reviewDrafts={};ui.email='';ui.sent=false;ui.error='';redraw()}catch(error){ui.error=error.message;redraw()}}
  });
  const authHash=new URLSearchParams(location.hash.slice(1));
  if(authHash.has('access_token')) {
    const access_token=authHash.get('access_token'),refresh_token=authHash.get('refresh_token');
    history.replaceState(null,'',location.pathname+'#teach');ui.loading=true;
    api('session',{access_token,refresh_token}).then(()=>{ui.loading=false;return load()}).catch(error=>{ui.loading=false;ui.loaded=true;ui.error=error.message;load();redraw()});
  } else if(authHash.has('error_description')) {ui.error=authHash.get('error_description');history.replaceState(null,'',location.pathname+'#teach');}
  return { handles: page=>Object.hasOwn(pages,page), render: shell, afterRender(){if(!ui.loaded&&!ui.loading)load()}, title: page=>pages[page] };
})();
